\label{lem:regular}
Any connected Cayley graph $\mathrm{Cay}(P,T)$ ($|T|=k$) is $k$-regular; consequently the number of edges
of the Cayley graph is given by $|E(\mathrm{Cay}(P,T))|=|P|k/2$.

\label{fact:sumtrans}
For any connected graph $\Delta$, $\sum_{v}Tr(v)=2W(\Delta)$, where $W$ is the Wiener index
in connection to the topological indices \cite{Wiener1947}.

\label{lem:distadd}
$\displaystyle d_\Gamma\big((x_i),(y_i)\big)=\sum_{i=1}^rd_{\Gamma_i}(x_i,y_i)$ for all
$(x_i),(y_i)\in G$.

\label{fact:orthgen}
For $\chi,\chi'\in\mathrm{Irr}(P)$, $\langle\chi,\chi'\rangle:=\frac1{|P|}\sum_{g\in P}\chi(g)\overline{\chi'(g)}
=\delta_{\chi,\chi'}$.

\label{lem:chiP}
Let $\chi_0\in\mathrm{Irr}(P)$ be the trivial character. Then $\chi_0(P)=|P|$; for $\chi\ne\chi_0$,
$\chi(P)=0$.

$\chi_0(P)=\sum_{g\in P}\chi_0(g)=\sum_{g\in P}1=|P|$. For $\chi\ne\chi_0$: by
Fact~\ref{fact:orthgen}, $\langle\chi,\chi_0\rangle=\frac1{|P|}\sum_g\chi(g)\overline{\chi_0(g)}
=\frac1{|P|}\sum_g\chi(g)=\frac1{|P|}\chi(P)$ (as $\chi_0\equiv1$) equals $0$, so $\chi(P)=0$.

\label{lem:normal-layers}
If $T\subseteq P\setminus\{1\}$ is symmetric, generating, normal, then every layer $T_j$ of
$\mathrm{Cay}(P,T)$ is normal.

\label{cor:simple}
$t=\sum_it_i\prod_{j\ne i}n_j$ is the largest eigenvalue of $D(\Gamma)$, with multiplicity $1$;
equivalently, $0$ is the smallest eigenvalue of $D^L(\Gamma)$, with multiplicity $1$, and $2t$ is
the largest eigenvalue of $D^Q(\Gamma)$, with multiplicity $1$.
